<template>
  <div class="docnet-project-list">
    <!-- Toolbar: status filter + create button -->
    <div class="row items-center justify-between q-mb-md">
      <div class="project-filters">
        <q-btn-toggle
          v-model="statusFilter"
          no-caps
          rounded
          unelevated
          toggle-color="primary"
          color="white"
          text-color="primary"
          :options="filterOptions"
          class="project-filter-toggle"
        />
      </div>
      <q-btn
        color="primary"
        icon="add"
        :label="$t('docnet_new_project')"
        no-caps
        unelevated
        rounded
        @click="showCreateDialog = true"
      />
    </div>

    <!-- Create Project Dialog -->
    <q-dialog v-model="showCreateDialog">
      <q-card style="min-width: 480px; max-width: 560px">
        <q-card-section>
          <div class="text-h6">{{ $t('docnet_create_project') }}</div>
          <p class="text-body2 text-grey-7 q-mt-xs q-mb-none" style="line-height: 1.5">
            {{ $t('docnet_create_project_description') }}
          </p>
        </q-card-section>

        <q-card-section class="q-pt-none column q-gutter-sm">
          <q-input
            v-model="newProject.name"
            :label="$t('docnet_project_name')"
            :hint="$t('docnet_project_name_hint')"
            outlined
            dense
            :rules="[val => !!val || $t('docnet_project_name_required')]"
          />
          <q-input
            v-model="newProject.description"
            :label="$t('docnet_description')"
            :hint="$t('docnet_project_description_hint')"
            outlined
            dense
            type="textarea"
            autogrow
          />
          <q-input
            v-model="newProject.due_date"
            :label="$t('docnet_due_date')"
            outlined
            dense
            type="date"
          />
        </q-card-section>

        <q-card-actions align="right">
          <q-btn flat :label="$t('docnet_cancel')" v-close-popup />
          <q-btn
            color="primary"
            :label="$t('docnet_create_project_btn')"
            :loading="creating"
            :disable="!newProject.name"
            @click="onCreateProject"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Edit Project Dialog -->
    <q-dialog v-model="showEditDialog">
      <q-card style="min-width: 480px; max-width: 560px">
        <q-card-section>
          <div class="text-h6">{{ $t('docnet_edit_project_title') }}</div>
        </q-card-section>

        <q-card-section class="q-pt-none column q-gutter-sm">
          <q-input
            v-model="editProject.name"
            :label="$t('docnet_project_name')"
            outlined
            dense
            :rules="[val => !!val || $t('docnet_project_name_required')]"
          />
          <q-input
            v-model="editProject.description"
            :label="$t('docnet_description')"
            outlined
            dense
            type="textarea"
            autogrow
          />
          <q-select
            v-model="editProject.status"
            :label="$t('docnet_status')"
            :options="statusSelectOptions"
            outlined
            dense
            emit-value
            map-options
          />
          <q-input
            v-model="editProject.due_date"
            :label="$t('docnet_due_date')"
            outlined
            dense
            type="date"
          />
        </q-card-section>

        <q-card-actions align="right">
          <q-btn flat :label="$t('docnet_cancel')" v-close-popup />
          <q-btn
            color="primary"
            :label="$t('docnet_save')"
            :loading="saving"
            :disable="!editProject.name"
            @click="onSaveProject"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Delete Confirmation Dialog -->
    <q-dialog v-model="showDeleteDialog">
      <q-card style="min-width: 350px">
        <q-card-section>
          <div class="text-h6">{{ $t('docnet_delete_project_title') }}</div>
        </q-card-section>
        <q-card-section class="q-pt-none">
          {{ $t('docnet_delete_project_confirm_short', { name: deleteTarget?.name }) }}
        </q-card-section>
        <q-card-actions align="right">
          <q-btn flat :label="$t('docnet_cancel')" v-close-popup />
          <q-btn color="negative" :label="$t('docnet_delete')" :loading="deleting" @click="onDeleteProject" />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Loading -->
    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <!-- Empty -->
    <div v-else-if="filteredProjects.length === 0" class="text-center q-pa-xl">
      <q-icon name="folder_open" size="64px" color="grey-5" />
      <p class="q-mt-md text-grey-6" style="max-width: 400px; margin-left: auto; margin-right: auto;">
        <template v-if="statusFilter === 'all'">
          <strong>{{ $t('docnet_no_projects_yet') }}</strong><br />
          {{ $t('docnet_no_projects_description') }}
        </template>
        <template v-else>
          {{ $t('docnet_no_status_projects', { status: statusFilterLabel }) }}
        </template>
      </p>
    </div>

    <!-- Project tree list -->
    <div v-else class="project-tree">
      <ProjectTreeItem
        v-for="project in filteredProjects"
        :key="project.id"
        :project="project"
        @select="$router.push('/doc-net/projects/' + project.id)"
        @select-mission="(m) => $router.push('/doc-net/missions/' + m.id)"
        @edit="openEditDialog"
        @delete="openDeleteDialog"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { useDocNetProjectStore } from 'src/store/DocNet/docnet-projects.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { storeToRefs } from 'pinia';

import type { DocNetProject } from 'src/@types/docnet';
import ProjectTreeItem from './components/ProjectTreeItem.vue';

export default defineComponent({
  name: 'DocNetProjectList',

  components: {
    ProjectTreeItem,
  },

  setup() {
    const projectStore = useDocNetProjectStore();
    const { projects, loading } = storeToRefs(projectStore);
    return { projectStore, projects, loading };
  },

  data() {
    return {
      statusFilter: 'all' as string,
      showCreateDialog: false,
      newProject: { name: '', description: '', due_date: '' },
      creating: false,
      showEditDialog: false,
      editProject: { id: '', name: '', description: '', status: 'active', due_date: '' },
      saving: false,
      showDeleteDialog: false,
      deleteTarget: null as DocNetProject | null,
      deleting: false,
    };
  },

  computed: {
    filterOptions() {
      return [
        { label: this.$t('docnet_all'), value: 'all' },
        { label: this.$t('docnet_active'), value: 'active' },
        { label: this.$t('docnet_completed'), value: 'completed' },
      ];
    },

    statusFilterLabel() {
      const match = this.filterOptions.find((o) => o.value === this.statusFilter);
      return match ? match.label : this.statusFilter;
    },

    statusSelectOptions() {
      return [
        { label: this.$t('docnet_active'), value: 'active' },
        { label: this.$t('docnet_completed'), value: 'completed' },
      ];
    },

    filteredProjects(): DocNetProject[] {
      if (this.statusFilter === 'all') {
        return this.projects;
      }
      return this.projects.filter((p) => p.status === this.statusFilter);
    },
  },

  methods: {
    async onCreateProject() {
      this.creating = true;
      try {
        const payload: Record<string, string> = { name: this.newProject.name };
        if (this.newProject.description) payload.description = this.newProject.description;
        if (this.newProject.due_date) payload.due_date = this.newProject.due_date;
        const project = await this.projectStore.createProject(payload);
        this.showCreateDialog = false;
        this.newProject = { name: '', description: '', due_date: '' };
        this.$router.push('/doc-net/projects/' + project.id);
      } catch (error) {
        console.error('Failed to create project:', error);
      } finally {
        this.creating = false;
      }
    },

    openEditDialog(project: DocNetProject) {
      this.editProject = {
        id: project.id,
        name: project.name,
        description: project.description || '',
        status: project.status,
        due_date: project.due_date
          ? new Date(project.due_date).toISOString().split('T')[0]
          : '',
      };
      this.showEditDialog = true;
    },

    async onSaveProject() {
      this.saving = true;
      try {
        const payload: Record<string, string | null> = {
          name: this.editProject.name,
          description: this.editProject.description || null,
          status: this.editProject.status,
          due_date: this.editProject.due_date || null,
        };
        await this.projectStore.updateProject(this.editProject.id, payload);
        this.showEditDialog = false;
        notify.success(this.$t('docnet_project_updated'));
      } catch (error) {
        console.error('Failed to update project:', error);
        notify.error(this.$t('docnet_update_project_failed'));
      } finally {
        this.saving = false;
      }
    },

    openDeleteDialog(project: DocNetProject) {
      this.deleteTarget = project;
      this.showDeleteDialog = true;
    },

    async onDeleteProject() {
      if (!this.deleteTarget) return;
      this.deleting = true;
      try {
        await this.projectStore.deleteProject(this.deleteTarget.id);
        this.showDeleteDialog = false;
        this.deleteTarget = null;
        notify.success(this.$t('docnet_project_deleted'));
      } catch (error) {
        console.error('Failed to delete project:', error);
        notify.error(this.$t('docnet_delete_project_failed'));
      } finally {
        this.deleting = false;
      }
    },
  },

  async mounted() {
    await this.projectStore.fetchProjects();
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().subscribe(`projects:${orgId}`);
    }
  },

  beforeUnmount() {
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().unsubscribe(`projects:${orgId}`);
    }
  },
});
</script>

<style lang="scss" scoped>
.docnet-project-list {
  max-width: 100%;
}

.project-filters {
  .project-filter-toggle {
    border: 1px solid var(--dashboard-border-color, rgba(0, 0, 0, 0.08));
    border-radius: 8px;
  }
}

.project-tree {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

body.body--dark {
  .project-filter-toggle {
    border-color: var(--dashboard-border-color, rgba(255, 255, 255, 0.1));
  }
}
</style>
